import React from "react";
import "./Item.css";
import { FaStar, FaStarHalfAlt, FaRegStar } from "react-icons/fa";

const Item = ({ image, name, new_price, old_price, rating }) => {
  return (
    <div className="item-card">
      <div className="item-image-container">
        <img src={image} alt={name} className="item-image" />
      </div>
      <div className="item-details">
        <h3 className="item-name">{name}</h3>
        <div className="item-prices">
          <span className="new-price">${new_price}</span>
          <span className="old-price">${old_price}</span>
        </div>
      </div>
      <div className="item-rating">
        {Array.from({ length: 5 }).map((_, i) => {
          const starValue = i + 1;
          if (starValue <= rating) return <FaStar key={i} />;
          else if (starValue - rating === 0.5) return <FaStarHalfAlt key={i} />;
          else return <FaRegStar key={i} />;
        })}
      </div>
    </div>
  );
};

export default Item;
